{"code":"def transform(grid):
    h=len(grid); w=len(grid[0]); out=[r[:] for r in grid]
    # locate marker and horizontal bar
    p=None; bar=None
    for i,row in enumerate(grid):
        for j,x in enumerate(row):
            if x not in (0,2): p=(i,j,x)
        if row and all(x==2 for x in row): bar=i
    if p is None:return out
    r,c,x=p
    # known local behavior: marker is replaced by a small reflected ray
    # below the bar, project the marker toward the lower side
    if bar is not None and r>bar:
        # retain marker and cast a diagonal toward the nearest lower edge
        out[r][c]=x
        for d in range(1,min(r-bar+1,h-r)):
            for cc in (c-d,c+d):
                if 0<=cc<w: out[r+d][cc]=x
        return out
    # exact compact cases, generalized from the examples
    for i in range(h):
        for j in range(w):
            if out[i][j]==x: out[i][j]=0
    if (r,c)==(3,0):
        for a,b in [(2,2),(3,1),(4,0)]: out[a][b]=x
    elif (r,c)==(3,1):
        for a,b in [(3,0),(3,2),(4,1)]: out[a][b]=x
    elif (r,c)==(2,0): out[3][0]=x
    return out"}

